display NDXJournalPos dispJournalPos()
{
    if (this.LineNum)
    {
        return int2str(real2int(this.LineNum));
    }
    else
    {
        return "";
    }
}

static void SumPerWrkCtr(Date _fromDate, Date _toDate, ResResourceType _resourceType)
{
    NDXResourcesStatistic       nDX_ResourceStatistic;
    NDXResourcesStatisticLine   nDX_ResourceStatisticLine;
    NDXResourcesStatisticLine   nDX_ResourceStatisticLineSum;
    JmgIpcActivity              jmgIpcActivity;

    Query                   q, q2;
    QueryRun                qr, qr2;
    QueryBuildDataSource    qbds, qbds2;
    QueryBuildFieldList     fields;
    NDXBDEInterruption      disruption;
    NDXCostUnit             nDX_CostUnit;

    // Summen je Produktionstag je Kostenstelle je Ressource bilden
    q       = new Query();
    qbds    = q.addDataSource(tablenum(NDXResourcesStatisticLine));
    qbds.addRange(fieldnum(NDXResourcesStatisticLine, ProdDate)).value(queryValue(_fromDate) + '..' + queryValue(_toDate));
    qbds.addRange(fieldnum(NDXResourcesStatisticLine, ResResourceType)).value(QueryValue(_resourceType));
    qbds.orderMode(OrderMode::GroupBy);
    qbds.addSortField(fieldnum(NDXResourcesStatisticLine, ProdDate));

    switch (_resourceType)
    {
        case ResResourceType::Personnel:   // Sortierung nach Produktionstag, Mitarbeiter, Kostenstelle
            //TODO Test groupBy statt softField
            qbds.addGroupByField(fieldnum(NDXResourcesStatisticLine, PersonnelNumber));
            qbds.addGroupByField(FieldId2Ext(fieldnum(NDXResourcesStatisticLine, Dimension_WrkCtr), 2));       // Kostenstelle
            break;
        default                         :   // Sortierung nach Produktionstag, Kostenstelle, Ressource
            qbds.addSortField(FieldId2Ext(fieldnum(NDXResourcesStatisticLine, Dimension_WrkCtr), 2));       // Kostenstelle
            qbds.addSortField(fieldnum(NDXResourcesStatisticLine, WrkCtrId));
            break;
    }
    qr      = new QueryRun(q);
    while (qr.next())
    {
        nDX_ResourceStatisticLine = qr.get(tablenum(NDXResourcesStatisticLine));

        //ToDo:nDX_CostUnit = nDX_ResourceStatisticLine.Dimension_WrkCtr.getFieldValue("KostenStelle");

        nDX_ResourceStatistic     = NDXResourcesStatistic::findOrCreate(nDX_ResourceStatisticLine.ProdDate, nDX_CostUnit,
                                                                    nDX_ResourceStatisticLine.WrkCtrId,
                                                                    nDX_ResourceStatisticLine.PersonnelNumber,
                                                                    _resourceType,
                                                                    true);


        // Anzahl Sekunden je TransactionType
        q2      = new Query();
        qbds2   = q2.addDataSource(tablenum(NDXResourcesStatisticLine));
        qbds2.addRange(fieldnum(NDXResourcesStatisticLine, ResResourceType)).value(QueryValue(_resourceType));
        qbds2.addRange(fieldnum(NDXResourcesStatisticLine, ProdDate)).value(QueryValue(nDX_ResourceStatisticLine.ProdDate));
        qbds2.addRange(FieldId2Ext(fieldnum(NDXResourcesStatisticLine, Dimension_WrkCtr), 2)).value(nDX_CostUnit ? nDX_CostUnit : SysQuery::valueEmptyString());

        if (_resourceType == ResResourceType::Machine)
        {
            qbds2.addRange(fieldnum(NDXResourcesStatisticLine, WrkCtrId)).value(nDX_ResourceStatisticLine.WrkCtrId ? nDX_ResourceStatisticLine.WrkCtrId : SysQuery::valueEmptyString());
        }
        else
        {
            qbds2.addRange(fieldnum(NDXResourcesStatisticLine, PersonnelNumber)).value(nDX_ResourceStatisticLine.PersonnelNumber ? nDX_ResourceStatisticLine.PersonnelNumber : SysQuery::valueEmptyString());
        }

        fields = qbds2.fields();
        fields.addField(fieldnum(NDXResourcesStatisticLine, TimeSec), SelectionField::Sum);
        fields.addField(fieldnum(NDXResourcesStatisticLine, TimeSecRef), SelectionField::Sum);
        fields.addField(fieldnum(NDXResourcesStatisticLine, NetWeight), SelectionField::Sum);
        qbds2.orderMode(OrderMode::GroupBy);
        qbds2.addSortField(fieldnum(NDXResourcesStatisticLine, ProdDate));
        if (_resourceType == ResResourceType::Machine)
        {
            qbds2.addSortField(fieldnum(NDXResourcesStatisticLine, WrkCtrId));
        }
        else
        {
            qbds2.addSortField(fieldnum(NDXResourcesStatisticLine, PersonnelNumber));
        }

        qbds2.addSortField(fieldnum(NDXResourcesStatisticLine, RouteJobType));

        qr2 = new QueryRun(q2);
        while (qr2.next())
        {
            nDX_ResourceStatisticLineSum = qr2.get(tablenum(NDXResourcesStatisticLine));

            switch (nDX_ResourceStatisticLineSum.RouteJobType)
            {
                case NDXRouteJobType::Process      :
                    nDX_ResourceStatistic.SecProcessing     += nDX_ResourceStatisticLineSum.TimeSec;
                    nDX_ResourceStatistic.SecProcessingRef  += nDX_ResourceStatisticLineSum.TimeSecRef;
                    break;
                case NDXRouteJobType::Setup        :
                    nDX_ResourceStatistic.SecSettings       += nDX_ResourceStatisticLineSum.TimeSec;
                    nDX_ResourceStatistic.SecSettingsRef    += nDX_ResourceStatisticLineSum.TimeSecRef;
                    break;
                case NDXRouteJobType::Interruption   :
                    nDX_ResourceStatistic.SecDisruption     += nDX_ResourceStatisticLineSum.TimeSec;
                    break;
                default                             :
                    Warning(strfmt("@NDX:NDXResourcesStatisticInfo13", nDX_ResourceStatisticLineSum.RouteJobType));     // TransactionType [%1] wird noch nicht behandelt!
                    break;
            }
            nDX_ResourceStatistic.SecTotal                  += nDX_ResourceStatisticLineSum.TimeSec;
            nDX_ResourceStatistic.SecProdTimeRef            += nDX_ResourceStatisticLineSum.TimeSecRef;
            nDX_ResourceStatistic.NetWeight                 += (nDX_ResourceStatisticLineSum.NetWeight); // KG-Anzeige
        }

        // Summenermittlung BDE / Journal
        q2      = new Query();
        qbds2   = q2.addDataSource(tablenum(NDXResourcesStatisticLine));
        qbds2.addRange(fieldnum(NDXResourcesStatisticLine, ResResourceType)).value(QueryValue(_resourceType));
        qbds2.addRange(fieldnum(NDXResourcesStatisticLine, ProdDate)).value(QueryValue(nDX_ResourceStatisticLine.ProdDate));
        qbds2.addRange(FieldId2Ext(fieldnum(NDXResourcesStatisticLine, Dimension_WrkCtr), 2)).value(nDX_CostUnit ? nDX_CostUnit : SysQuery::valueEmptyString());

        if (_resourceType == ResResourceType::Machine)
        {
            qbds2.addRange(fieldnum(NDXResourcesStatisticLine, WrkCtrId)).value(nDX_ResourceStatisticLine.WrkCtrId ? nDX_ResourceStatisticLine.WrkCtrId : SysQuery::valueEmptyString());
        }
        else
        {
            qbds2.addRange(fieldnum(NDXResourcesStatisticLine, PersonnelNumber)).value(nDX_ResourceStatisticLine.PersonnelNumber ? nDX_ResourceStatisticLine.PersonnelNumber : SysQuery::valueEmptyString());
        }

        fields = qbds2.fields();
        fields.addField(fieldnum(NDXResourcesStatisticLine, TimeSec), SelectionField::Sum);
        fields.addField(fieldnum(NDXResourcesStatisticLine, TimeSecRef), SelectionField::Sum);
        qbds2.orderMode(OrderMode::GroupBy);
        qbds2.addSortField(fieldnum(NDXResourcesStatisticLine, ProdDate));

        if (_resourceType == ResResourceType::Machine)
        {
            qbds2.addSortField(fieldnum(NDXResourcesStatisticLine, WrkCtrId));
        }
        else
        {
            qbds2.addSortField(fieldnum(NDXResourcesStatisticLine, PersonnelNumber));
        }

        qbds2.addSortField(fieldnum(NDXResourcesStatisticLine, RouteJobType));
        qbds2.addSortField(fieldnum(NDXResourcesStatisticLine, ProductionTimeType));

        qr2 = new QueryRun(q2);
        while (qr2.next())
        {
            nDX_ResourceStatisticLineSum = qr2.get(tablenum(NDXResourcesStatisticLine));

            switch (nDX_ResourceStatisticLineSum.RouteJobType)
            {
                case NDXRouteJobType::Process      :
                switch (nDX_ResourceStatisticLineSum.ProductionTimeType)
                    {
                        case NDXProductionTimeType::BDE                :
                            nDX_ResourceStatistic.SecProcessingBDE     += nDX_ResourceStatisticLineSum.TimeSec;
                            break;
                        case NDXProductionTimeType::Journal            :
                            nDX_ResourceStatistic.SecProcessingJournal += nDX_ResourceStatisticLineSum.TimeSec;
                            break;
                    }
                    break;
                case NDXRouteJobType::Setup        :
                switch (nDX_ResourceStatisticLineSum.ProductionTimeType)
                    {
                        case NDXProductionTimeType::BDE                :
                            nDX_ResourceStatistic.SecSettingsBDE       += nDX_ResourceStatisticLineSum.TimeSec;
                            break;
                        case NDXProductionTimeType::Journal            :
                            nDX_ResourceStatistic.SecSettingsJournal   += nDX_ResourceStatisticLineSum.TimeSec;
                            break;
                    }
                    break;
                case NDXRouteJobType::Interruption:
                switch (nDX_ResourceStatisticLineSum.ProductionTimeType)
                    {
                        case NDXProductionTimeType::BDE                :
                            nDX_ResourceStatistic.SecDisruptionBDE     += nDX_ResourceStatisticLineSum.TimeSec;
                            break;
                        case NDXProductionTimeType::Journal            :
                            nDX_ResourceStatistic.SecDisruptionJournal += nDX_ResourceStatisticLineSum.TimeSec;
                            break;
                    }
                    break;
                default                             :
                    Warning(strfmt("@NDX:NDXResourcesStatisticInfo13", nDX_ResourceStatisticLineSum.RouteJobType));     // TransactionType [%1] wird noch nicht behandelt!
                    break;
            }
        }

        // Summen je Unterbrechung
        q2      = new Query();
        qbds2   = q2.addDataSource(tablenum(NDXResourcesStatisticLine));
        qbds2.addRange(fieldnum(NDXResourcesStatisticLine, ResResourceType)).value(QueryValue(_resourceType));              // 1.4: NDX/PAFFH/NDX_TASK1235003417/09.01.2013
        qbds2.addRange(fieldnum(NDXResourcesStatisticLine, ProdDate)).value(QueryValue(nDX_ResourceStatisticLine.ProdDate));

        if (nDX_CostUnit)
        {
            qbds2.addRange(FieldId2Ext(fieldnum(NDXResourcesStatisticLine, Dimension_WrkCtr), 2)).value(nDX_CostUnit);
        }
        else
        {
            qbds2.addRange(FieldId2Ext(fieldnum(NDXResourcesStatisticLine, Dimension_WrkCtr), 2)).value(SysQuery::valueEmptyString());
        }

        if (_resourceType == ResResourceType::Machine)
        {
            qbds2.addRange(fieldnum(NDXResourcesStatisticLine, WrkCtrId)).value(nDX_ResourceStatisticLine.WrkCtrId ? nDX_ResourceStatisticLine.WrkCtrId : SysQuery::valueEmptyString());
        }
        else if (_resourceType == ResResourceType::Personnel && nDX_ResourceStatisticLine.PersonnelNumber)
        {
            qbds2.addRange(fieldnum(NDXResourcesStatisticLine, PersonnelNumber)).value( nDX_ResourceStatisticLine.PersonnelNumber ? nDX_ResourceStatisticLine.PersonnelNumber : SysQuery::valueEmptyString());
        }

        qbds2.orderMode(OrderMode::GroupBy);
        qbds2.addGroupByField(fieldnum(NDXResourcesStatisticLine, ResResourceType));
        qbds2.addGroupByField(fieldnum(NDXResourcesStatisticLine, ProdDate));

        if (_resourceType == ResResourceType::Machine)
        {
            qbds2.addGroupByField(fieldnum(NDXResourcesStatisticLine, WrkCtrId));
        }
        else
        {
            qbds2.addGroupByField(fieldnum(NDXResourcesStatisticLine, PersonnelNumber));
        }

        qbds2.addGroupByField(fieldnum(NDXResourcesStatisticLine, RouteJobType));
        qbds2.addGroupByField(fieldnum(NDXResourcesStatisticLine, JobId));

        fields = qbds2.fields();
        fields.addField(fieldnum(NDXResourcesStatisticLine, TimeSec), SelectionField::Sum);
        fields.addField(fieldnum(NDXResourcesStatisticLine, TimeSecRef), SelectionField::Sum);
        fields.addField(fieldnum(NDXResourcesStatisticLine, JobId));

        qr2 = new QueryRun(q2);
        while (qr2.next())
        {
            nDX_ResourceStatisticLineSum    = qr2.get(tablenum(NDXResourcesStatisticLine));
            jmgIpcActivity = JmgIpcActivity::FindJobId(nDX_ResourceStatisticLineSum.JobId);

            if (jmgIpcActivity)
            {
                disruption = str2enum(disruption, jmgIpcActivity.Category);

                switch (disruption)
                {
                    case NDXBDEInterruption::U61  : nDX_ResourceStatistic.ProdSecU61    = nDX_ResourceStatisticLineSum.TimeSec; break;
                    case NDXBDEInterruption::U62  : nDX_ResourceStatistic.ProdSecU62    = nDX_ResourceStatisticLineSum.TimeSec; break;
                    case NDXBDEInterruption::U63  : nDX_ResourceStatistic.ProdSecU63    = nDX_ResourceStatisticLineSum.TimeSec; break;
                    case NDXBDEInterruption::U64  : nDX_ResourceStatistic.ProdSecU64    = nDX_ResourceStatisticLineSum.TimeSec; break;
                    case NDXBDEInterruption::U65  : nDX_ResourceStatistic.ProdSecU65    = nDX_ResourceStatisticLineSum.TimeSec; break;
                    case NDXBDEInterruption::U66  : nDX_ResourceStatistic.ProdSecU66    = nDX_ResourceStatisticLineSum.TimeSec; break;
                    case NDXBDEInterruption::U67  : nDX_ResourceStatistic.ProdSecU67    = nDX_ResourceStatisticLineSum.TimeSec; break;
                    case NDXBDEInterruption::U68  : nDX_ResourceStatistic.ProdSecU68    = nDX_ResourceStatisticLineSum.TimeSec; break;
                    case NDXBDEInterruption::U69  : nDX_ResourceStatistic.ProdSecU69    = nDX_ResourceStatisticLineSum.TimeSec; break;
                    case NDXBDEInterruption::U70  : nDX_ResourceStatistic.ProdSecU70    = nDX_ResourceStatisticLineSum.TimeSec; break;
                    case NDXBDEInterruption::GMK  : nDX_ResourceStatistic.ProdSecGMK    = nDX_ResourceStatisticLineSum.TimeSec; break;
                    default : Warning(strfmt("@NDX:NDXResourcesStatisticInfo12", jmgIpcActivity.Category));   // Unterbrechungsgrund [%1] wird nicht berücksichtigt!
                }
            }
        }
        ttsbegin;
        if (nDX_ResourceStatistic.validateWrite())
        {
            nDX_ResourceStatistic.update();
        }
        ttscommit;
    }
}
